export const getGetFlowPreviewUrl = (organizationId: string,
    flowId: string,
    params?: GetFlowPreviewParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/organizations/${organizationId}/flows/${flowId}/preview?${stringifiedParams}` : `/organizations/${organizationId}/flows/${flowId}/preview`
}

